import test from 'node:test';
import assert from 'node:assert/strict';
import { mergeCustomers, normalizeId } from '../src/customers.js';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';

test('mergeCustomers removes duplicate customer', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'standard' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.customers.length, 1);
  assert.equal(r.value.customers[0].id, 'C-002');
});

test('mergeCustomers reassigns invoices to target customer', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'standard' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-001', status: 'issued' },
    { customerId: 'C-001', number: 'INV-002', status: 'draft' },
    { customerId: 'C-002', number: 'INV-003', status: 'issued' },
  ];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 3);
  assert.equal(r.value.invoices[0].customerId, 'C-002');
  assert.equal(r.value.invoices[1].customerId, 'C-002');
  assert.equal(r.value.invoices[2].customerId, 'C-002');
});

test('mergeCustomers rejects same customer', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-001');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'SAME_CUSTOMER');
});

test('mergeCustomers rejects non-existent from customer', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-999', 'C-001');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers rejects non-existent into customer', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-999');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers normalizes customer IDs', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'standard' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [
    { customerId: 'c-001', number: 'INV-001', status: 'issued' },
  ];

  const r = mergeCustomers(customers, invoices, ' c-001 ', ' C-002 ');
  assert.equal(r.ok, true);
  assert.equal(r.value.customers.length, 1);
  assert.equal(r.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers does not mutate original arrays', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'standard' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-001', status: 'issued' },
  ];

  const originalCustomersLength = customers.length;
  const originalInvoicesLength = invoices.length;

  mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(customers.length, originalCustomersLength);
  assert.equal(invoices.length, originalInvoicesLength);
});

test('mergeCustomers with multiple invoices from same customer', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'standard' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-001', status: 'issued' },
    { customerId: 'C-001', number: 'INV-002', status: 'issued' },
    { customerId: 'C-001', number: 'INV-003', status: 'draft' },
  ];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  const fromC001 = r.value.invoices.filter((inv) => inv.customerId === 'C-001');
  const toC002 = r.value.invoices.filter((inv) => inv.customerId === 'C-002');
  assert.equal(fromC001.length, 0);
  assert.equal(toC002.length, 3);
});

test('mergeCustomers with empty invoices array', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'standard' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 0);
});

test('mergeCustomers with many customers', () => {
  const customers = [
    { id: 'C-001', name: 'A', email: 'a@example.com', country: 'NL', tier: 'standard' },
    { id: 'C-002', name: 'B', email: 'b@example.com', country: 'NL', tier: 'standard' },
    { id: 'C-003', name: 'C', email: 'c@example.com', country: 'NL', tier: 'standard' },
    { id: 'C-004', name: 'D', email: 'd@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-001', status: 'issued' },
  ];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-004');
  assert.equal(r.ok, true);
  assert.equal(r.value.customers.length, 3);
  assert.equal(r.value.customers.some((c) => c.id === 'C-001'), false);
  assert.equal(r.value.customers.some((c) => c.id === 'C-004'), true);
});

test('mergeCustomers preserves other customer properties', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'DE', tier: 'silver' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  const resultC002 = r.value.customers.find((c) => c.id === 'C-002');
  assert.equal(resultC002.name, 'Customer B');
  assert.equal(resultC002.email, 'b@example.com');
  assert.equal(resultC002.country, 'DE');
  assert.equal(resultC002.tier, 'silver');
});

test('mergeCustomers copies invoice properties', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'standard' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-001', status: 'issued', total: 10000 },
  ];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  const result = r.value.invoices[0];
  assert.equal(result.customerId, 'C-002');
  assert.equal(result.number, 'INV-001');
  assert.equal(result.status, 'issued');
  assert.equal(result.total, 10000);
});

test('mergeCustomers with mixed case customer IDs', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'standard' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-001', status: 'issued' },
  ];

  const r = mergeCustomers(customers, invoices, 'c-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers rejects if both customers not found', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-999', 'C-888');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers with invoices for multiple customers', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'standard' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
    { id: 'C-003', name: 'Customer C', email: 'c@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-001', status: 'issued' },
    { customerId: 'C-002', number: 'INV-002', status: 'issued' },
    { customerId: 'C-003', number: 'INV-003', status: 'issued' },
  ];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  const c001Invoices = r.value.invoices.filter((inv) => inv.customerId === 'C-001');
  const c002Invoices = r.value.invoices.filter((inv) => inv.customerId === 'C-002');
  const c003Invoices = r.value.invoices.filter((inv) => inv.customerId === 'C-003');
  assert.equal(c001Invoices.length, 0);
  assert.equal(c002Invoices.length, 2);
  assert.equal(c003Invoices.length, 1);
});

test('mergeCustomers preserves invoice order', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'standard' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-001', order: 1 },
    { customerId: 'C-002', number: 'INV-002', order: 2 },
    { customerId: 'C-001', number: 'INV-003', order: 3 },
  ];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices[0].order, 1);
  assert.equal(r.value.invoices[1].order, 2);
  assert.equal(r.value.invoices[2].order, 3);
});

